-- Triumph and Ducati exact-model factory-source research, 12 November 2026.
-- Preserves individual model year, market and edition: never apply RS figures
-- to R, Rally Pro chassis to GT Pro, or original 2020 V4 specs to later years.
-- Idempotent data import plus independent source verification audit recovery.
with documented(catalog_model_id,category,label,value,start_year,end_year,market,source_name,source_url,verification_basis,scope_note,source_version) as (values
(250,'model_year','Triumph Street Triple 765 — 2023 updated R and RS family','{"engine":"Liquid-cooled inline three-cylinder","torque":"80 Nm at 9,500 rpm","rs_power":"130 PS at 12,000 rpm","model_year":"2023","development":"Moto2-derived engine updates and shortened gearbox ratios","standard_r_power":"120 PS at 11,500 rpm","engine_capacity_cc":765}'::jsonb,2023,NULL,'Triumph international 2023 launch','Triumph Motorcycles — The new 2023 Street Triple 765 range, 3 November 2022','https://www.triumphmotorcycles.com/for-the-ride/news/motorcycles/street-triple-765-2022-11-03','manufacturer_primary_source_exact_model_checked_2026_11_12','Triumph 3 Nov 2022 release describes new-for-2023 R, RS and Moto2; family facts must not be assigned to pre-2023 Street Triples, older 675, or later revisions.','Triumph Motorcycles — The new 2023 Street Triple 765 range, 3 November 2022'),
(251,'specification','Triumph Street Triple 765 RS — 2023 RS engine and braking equipment','{"power":"130 PS at 12,000 rpm","brakes":"Brembo Stylema front brakes","torque":"80 Nm at 9,500 rpm","model_year":"2023","engineering":"Moto2-derived engine upgrades","engine_capacity_cc":765}'::jsonb,2023,NULL,'Triumph 2023 launch','Triumph Motorcycles — The new 2023 Street Triple 765 range, 3 November 2022','https://www.triumphmotorcycles.com/for-the-ride/news/motorcycles/street-triple-765-2022-11-03','manufacturer_primary_source_exact_model_checked_2026_11_12','2023 RS, not Street Triple R 120PS; avoid extending 2023 equipment into future years.','Triumph Motorcycles — The new 2023 Street Triple 765 range, 3 November 2022'),
(256,'engineering','Triumph Tiger 900 — 2024 generation T-Plane engine improvement','{"power":"108 PS","change":"13 PS increase versus outgoing Tiger 900 generation","engine":"T-Plane triple, 1-3-2 firing order","weight":"Range starts from 219 kg fully fuelled","model_year":"2024","engine_capacity_cc":888}'::jsonb,2024,NULL,'Triumph UK 2024 model family','Triumph Motorcycles — Tiger 900 Your Questions Our Answers, 25 April 2024','https://www.triumphmotorcycles.co.uk/for-the-ride/news/motorcycles/tiger-900-q-and-a-2024-05-28','manufacturer_primary_source_exact_model_checked_2026_11_12','Triumph 2024 family range, weight is lowest family bike, NOT assigned to every GT/Rally model or older 900.','Triumph Motorcycles — Tiger 900 Your Questions Our Answers, 25 April 2024'),
(257,'specification','Triumph Tiger 900 GT Pro — 2024-on manufacturer engine specification','{"power":"108 PS at 9,500 rpm","torque":"90 Nm at 6,850 rpm","gearbox":"Six speed","model_year":"2024 specification reference","rear_wheel":"17 inch cast alloy","engine_type":"DOHC liquid-cooled three-cylinder","front_wheel":"19 inch cast alloy","engine_capacity_cc":888}'::jsonb,2024,NULL,'Triumph UK manufacturer 2024-range reference','Triumph Motorcycles — Tiger 900 GT Pro factory specification','https://www.triumphmotorcycles.co.uk/motorcycles/adventure/tiger-900/specification','manufacturer_primary_source_exact_model_checked_2026_11_12','Triumph published GT Pro spec for 2024-generation range; dynamic page may later change; record scoped to current documented generation, not claimed for 2020-era GT Pro.','Triumph Motorcycles — Tiger 900 GT Pro factory specification'),
(258,'chassis','Triumph Tiger 900 Rally Pro — 2024 adventure chassis distinction','{"model_year":"2024","rear_wheel":"17-inch spoked tubeless","front_wheel":"21-inch spoked tubeless","front_brakes":"Twin 320 mm discs, Brembo Stylema calipers","rear_suspension":"Showa 230 mm travel","front_suspension":"Showa 45 mm USD forks, 240 mm travel","engine_capacity_cc":888}'::jsonb,2024,NULL,'Triumph UK 2024 Rally Pro','Triumph Motorcycles — Tiger 900 Rally Pro 2024 factory specification','https://www.triumphmotorcycles.co.uk/motorcycles/adventure/tiger-900/tiger-900-rally-pro-2024','manufacturer_primary_source_exact_model_checked_2026_11_12','Specifically 2024 Rally Pro, not the cast-wheel road-oriented GT Pro.','Triumph Motorcycles — Tiger 900 Rally Pro 2024 factory specification'),
(102,'market_launch','Ducati Monster 937 — 2020 announcement and April 2021 dealer launch','{"engine":"Testastretta 11-degree desmodromic L-twin","model_year":"2021 new-generation Monster","announcement_date":"2 December 2020","dealership_arrival":"April 2021","engine_capacity_cc":937}'::jsonb,2021,NULL,'Ducati international','Ducati Media House — Light, compact, accessible and fun, 2 Dec 2020','https://mediahouse.ducati.com/light-compact-accessible-and-fun-ducati-presents-new-monster/?lang=eng','manufacturer_primary_source_exact_model_checked_2026_11_12','2020 announcement, 2021 release; exact 937cc generation not older Monster 821/1200 or 2026 replacement.','Ducati Media House — Light, compact, accessible and fun, 2 Dec 2020'),
(102,'engineering','Ducati Monster 937 — 2021 Testastretta 11-degree generation','{"frame":"Superbike-derived aluminium front frame","power":"111 hp at 9,250 rpm","torque":"9.5 kgm at 6,500 rpm","gearbox":"Ducati Quick Shift Up/Down fitted as standard","dry_weight":"166 kg","model_year":"2021","engine_capacity_cc":937}'::jsonb,2021,NULL,'Ducati international 2021 version','Ducati — Production of the new Monster begins, 2021','https://www.ducati.com/gb/en/news/production-of-the-new-monster-begins','manufacturer_primary_source_exact_model_checked_2026_11_12','Source specifies 937 Monster introduced 2021, not timeless Monster family. Torque preserved in original manufacturer unit rather than website typo.','Ducati — Production of the new Monster begins, 2021'),
(104,'engineering','Ducati Multistrada V4 — original 2020 V4 Granturismo powertrain introduction','{"power":"170 hp at 10,500 rpm","torque":"125 Nm at 8,750 rpm","service":"60,000 km valve clearance check interval","technology":"Rear cylinder bank deactivation at idle","engine_type":"90-degree liquid-cooled V4 Granturismo","announcement_year":"2020","engine_capacity_cc":1158}'::jsonb,2020,NULL,'Ducati original V4 Granturismo announcement','Ducati — V4 Granturismo: engine for the next generation of Multistrada','https://www.ducati.com/ww/en/news/v4-granturismo-the-engine-for-the-nextgeneration-of-ducati-multistrada','manufacturer_primary_source_exact_model_checked_2026_11_12','Original 2020 engine announcement. Current model-page specs (170hp at 10750, 124Nm at 9000) differ; avoid mixing versions; do not describe as the current 2026 specification.','Ducati — V4 Granturismo: engine for the next generation of Multistrada')
)
insert into public.motorcycle_catalog_facts(catalog_model_id,category,label,value,start_year,end_year,market,source_name,source_url,verification_status)
select d.catalog_model_id,d.category,d.label,d.value,d.start_year,d.end_year,d.market,d.source_name,d.source_url,'verified' from documented d
where exists(select 1 from public.motorcycle_catalog_dropdown_clean m where m.model_id=d.catalog_model_id)
and not exists(select 1 from public.motorcycle_catalog_facts f where f.catalog_model_id=d.catalog_model_id and f.label=d.label and f.source_url=d.source_url);

with documented(catalog_model_id,label,source_url,verification_basis,scope_note,source_version) as (values
(250,'Triumph Street Triple 765 — 2023 updated R and RS family','https://www.triumphmotorcycles.com/for-the-ride/news/motorcycles/street-triple-765-2022-11-03','manufacturer_primary_source_exact_model_checked_2026_11_12','Triumph 3 Nov 2022 release describes new-for-2023 R, RS and Moto2; family facts must not be assigned to pre-2023 Street Triples, older 675, or later revisions.','Triumph Motorcycles — The new 2023 Street Triple 765 range, 3 November 2022'),
